"use strict";(self.webpackChunkselfcustodylabs=self.webpackChunkselfcustodylabs||[]).push([["4241"],{66984(e){e.exports=JSON.parse('{"tag":{"label":"bios","permalink":"/docs/tags/bios","allTagsPath":"/docs/tags","count":12,"items":[{"id":"coreboot/build","title":"Build Coreboot","description":"Build Coreboot from source on Linux: install the dependencies, clone the source tree, build the cross-compiler toolchain, configure your ThinkPad and compile.","permalink":"/docs/coreboot/build"},{"id":"coreboot/requirements","title":"Coreboot Hardware Requirements","description":"What you need to install Coreboot on a ThinkPad: a supported model, a Linux machine and, for external flashing, a Raspberry Pi Pico plus a clip or pogo pins.","permalink":"/docs/coreboot/requirements"},{"id":"coreboot/README","title":"Coreboot Installation Guide","description":"Install Coreboot open-source firmware for a fast, secure, and transparent boot process. Perfect for Bitcoin nodes and security-focused setups.","permalink":"/docs/coreboot/"},{"id":"coreboot/internal/downgrading-bios","title":"Downgrading BIOS","description":"Downgrade your laptop\'s stock BIOS to a version with an unlocked Intel ME region, a prerequisite for internal Coreboot flashing.","permalink":"/docs/coreboot/internal/downgrading-bios"},{"id":"coreboot/external-flashing","title":"External Flashing","description":"Flash Coreboot with an external SPI programmer: detect the chip, back up the factory BIOS, neutralise Intel ME, write the image and confirm ME is disabled.","permalink":"/docs/coreboot/external-flashing"},{"id":"coreboot/internal/flashing-bios","title":"Flash Coreboot to Your Laptop BIOS","description":"Flash Coreboot from inside a running system after the BIOS region is unlocked. Includes safety checks and verification of the flashed image.","permalink":"/docs/coreboot/internal/flashing-bios"},{"id":"libreboot/flashing-bios","title":"Flash Libreboot to Your Laptop BIOS","description":"Flash a Libreboot ROM onto your laptop with an external SPI programmer: locate the chips, split the ROM, detect, and write the new firmware.","permalink":"/docs/libreboot/flashing-bios"},{"id":"coreboot/internal/index","title":"Internal Coreboot Flashing","description":"Flash Coreboot from inside a running system: downgrade your stock BIOS, unlock the Intel Flash Descriptor, and write the new firmware safely.","permalink":"/docs/coreboot/internal"},{"id":"libreboot/requirements","title":"Libreboot Hardware Requirements","description":"Hardware list for flashing Libreboot: supported laptops, Raspberry Pi Pico H programmer, Pomona SOIC8 clip, and required cables.","permalink":"/docs/libreboot/requirements"},{"id":"libreboot/README","title":"Libreboot Installation Guide","description":"Install Libreboot on a ThinkPad with a Raspberry Pi Pico: open-source coreboot firmware that strips and disables Intel\'s ME on your Bitcoin computer.","permalink":"/docs/libreboot/"},{"id":"coreboot/internal/unlocking-bios","title":"Unlocking BIOS","description":"Unlock the Intel Flash Descriptor BIOS region with CHIPSEC so Coreboot can be flashed internally without an external SPI programmer.","permalink":"/docs/coreboot/internal/unlocking-bios"},{"id":"libreboot/update-bios","title":"Update Libreboot Firmware","description":"Update an existing Libreboot install from inside Linux without opening the laptop: relax /dev/mem access, back up the chip, write the new ROM and verify it.","permalink":"/docs/libreboot/update-bios"}],"unlisted":false}}')}}]);